// Pixel drawing for Slimy. Sprites come from /sprites.json, generated by
// tools/make_slime.py for the app and its widgets. One canvas pixel is one
// sprite pixel; CSS scales the canvas with image-rendering: pixelated.
//
// Also used by the admin area (site/admin/lib/slime.js): keep SKINS,
// SKIN_TITLES, loadSprites() and the Slime class compatible.

// Shared/Art/Skin.swift: body, shade, ink, shine.
export const SKINS = {
  lime: ["#7DE67A", "#3DAA5A", "#143028", "#F0FFF0"],
  bubblegum: ["#FF9FCB", "#E0609A", "#3A1228", "#FFF0F7"],
  ocean: ["#7CC8FF", "#3A86D9", "#0F2240", "#EFF8FF"],
  grape: ["#B59BFF", "#7A5BE0", "#22164A", "#F4F0FF"],
  lava: ["#FF9A5C", "#E0532F", "#3A140A", "#FFF3E8"],
  gold: ["#FFD86B", "#E0A42F", "#3A2A08", "#FFFBEA"],
  ghost: ["#E8F0FF", "#A9B6D8", "#2A3048", "#FFFFFF"],
  void: ["#2A2540", "#1A1630", "#9B7BFF", "#D9CCFF"],
};
export const SKIN_TITLES = {
  lime: "Lime", bubblegum: "Bubblegum", ocean: "Ocean", grape: "Grape",
  lava: "Lava", gold: "Gold", ghost: "Ghost", void: "Hypr Void",
};
/// Skin.unlockLevel
export const SKIN_LEVELS = { lime: 1, bubblegum: 2, ocean: 3, grape: 4, lava: 6, gold: 8, ghost: 10, void: 15 };

// Shared/Art/Brand.swift
export const WARM = "#F07A9A";
export const COOL = "#7FD6F0";
export const BRAND = { slime: "#7DE67A", gold: "#FFD166", danger: "#E85D5D", warm: WARM, cool: COOL };

// Shared/Art/Emotes.swift, EmoteReel.color
export const REEL_COLORS = {
  happyA: WARM, happyB: WARM, happyC: WARM, love: WARM,
  hunger: "#F2A65A", fun: "#6CC4E8", clean: "#7FD9B0",
  sleepy: COOL, night: COOL, confused: COOL,
  battery: BRAND.danger, zap: BRAND.gold, morning: BRAND.gold, wifi: BRAND.slime,
};

export const motion = matchMedia("(prefers-reduced-motion: reduce)");
export const calm = () => motion.matches;

// ------------------------------------------------------------ sprites

let DATA = null;
let pending;
/// Loads /sprites.json once. Resolves to the sprite data.
export function loadSprites() {
  pending ??= fetch("/sprites.json")
    .then((r) => {
      if (!r.ok) throw new Error("sprites " + r.status);
      return r.json();
    })
    .then((d) => (DATA = d));
  return pending;
}
export const sprites = () => DATA;

export const hex = (n) => "#" + n.toString(16).padStart(6, "0");

const paletteCache = new Map();
function palette(obj) {
  let p = paletteCache.get(obj);
  if (!p) {
    p = Object.fromEntries(Object.entries(obj).map(([k, v]) => [k, hex(v)]));
    paletteCache.set(obj, p);
  }
  return p;
}

export function skinColors(skin) {
  const [b, s, k, w] = Object.hasOwn(SKINS, skin ?? "") ? SKINS[skin] : SKINS.lime;
  return { b, s, k, w, r: WARM, c: COOL };
}

/// Paints character rows; `colors` maps a character to a CSS colour.
export function paint(ctx, rows, colors, ox = 0, oy = 0, mirror = false) {
  const w = rows[0]?.length ?? 0;
  for (let y = 0; y < rows.length; y++) {
    const row = rows[y];
    for (let x = 0; x < row.length; x++) {
      const fill = colors[row[x]];
      if (!fill) continue;
      let end = x;
      while (end + 1 < row.length && row[end + 1] === row[x]) end++;
      ctx.fillStyle = fill;
      ctx.fillRect(ox + (mirror ? w - 1 - end : x), oy + y, end - x + 1, 1);
      x = end;
    }
  }
}

export function frames(stage, anim) {
  const f = DATA.frames;
  return f[`${stage}.${anim}`] ?? f[`${stage}.idle`] ?? f["young.idle"];
}

/// [top, eyeY, neckY, look, dx] for a frame, like the app's anchors.
export function anchorFor(stage, anim, i) {
  const key = DATA.frames[`${stage}.${anim}`] ? `${stage}.${anim}` : `${stage}.idle`;
  const list = DATA.anchors[key];
  return list ? list[i % list.length] : null;
}

/// Puts an accessory onto a frame, like AccessoryPlacer in Shared/Art/PixelSprites.swift.
function placeAccessory(acc, frame, anchor) {
  const W = DATA.width, H = DATA.height;
  const grid = Array.from({ length: H }, () => Array(W).fill("."));
  const put = (x, y, c) => {
    if (x >= 0 && x < W && y >= 0 && y < H) grid[y][x] = c;
  };
  const cx = Math.floor((W - 1) / 2) + 1;
  const [top, ey, neck, look, dx = 0] = anchor;
  const rows = acc.rows;
  if (acc.kind === "hat") {
    const x0 = cx - Math.floor((rows[0]?.length ?? 0) / 2) + dx;
    const y0 = top - rows.length + 1;
    rows.forEach((row, r) => [...row].forEach((ch, c) => ch !== "." && put(x0 + c, y0 + r, ch)));
  } else if (acc.kind === "glasses") {
    const x0 = cx - Math.floor((rows[0]?.length ?? 0) / 2) + look + dx;
    rows.forEach((row, r) => [...row].forEach((ch, c) => ch !== "." && put(x0 + c, ey - 1 + r, ch)));
  } else if (acc.kind === "scarf") {
    const span = (y) => {
      if (y < 0 || y >= frame.length) return null;
      const chars = frame[y];
      let a = -1, b = -1;
      for (let i = 0; i < chars.length; i++) if ("bsk".includes(chars[i])) { if (a < 0) a = i; b = i; }
      return a < 0 ? null : [a, b];
    };
    [neck, neck + 1].forEach((y, i) => {
      const s = span(y);
      if (!s) return;
      for (let x = s[0]; x <= s[1]; x++) put(x, y, (x + i) % 3 === 0 ? "b" : "a");
    });
    const s = span(neck);
    if (s) {
      put(s[0] + 3, neck + 2, "a");
      put(s[0] + 3, neck + 3, "b");
    }
  }
  return grid.map((r) => r.join(""));
}

/// Draws one slime frame with its accessories. `look` = {stage, skin, hat, glasses, scarf}.
export function drawSlime(ctx, look, anim, i, ox = 0, oy = 0, mirror = false) {
  const stage = look.stage || "young";
  const list = frames(stage, anim);
  const n = i % list.length;
  const rows = list[n];
  paint(ctx, rows, skinColors(look.skin), ox, oy, mirror);
  const anchor = anchorFor(stage, anim, n);
  if (!anchor) return;
  for (const item of [look.scarf, look.glasses, look.hat]) {
    const acc = item && DATA.accessories[item];
    if (!acc) continue;
    paint(ctx, placeAccessory(acc, rows, anchor), palette(acc.palette), ox, oy, mirror);
  }
}

export function itemSize(name) {
  const it = DATA.items[name];
  return it ? [it.rows[0].length, it.rows.length] : [0, 0];
}

export function drawItemAt(ctx, name, x, y) {
  const it = DATA.items[name];
  if (it) paint(ctx, it.rows, palette(it.palette), x, y);
}

/// A still item sprite on its own canvas (food, heart, coin …), `scale` CSS pixels per sprite pixel.
export function itemCanvas(name, scale = 3, canvas = document.createElement("canvas")) {
  const [w, h] = itemSize(name);
  canvas.width = w || 1;
  canvas.height = h || 1;
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawItemAt(ctx, name, 0, 0);
  canvas.style.width = w * scale + "px";
  canvas.style.height = h * scale + "px";
  canvas.setAttribute("aria-hidden", "true");
  return canvas;
}

/// Fills every <canvas data-item="name" data-scale="3"> below `root`.
export function drawAllItems(root = document) {
  const run = () => root.querySelectorAll("canvas[data-item]").forEach((c) => {
    itemCanvas(c.dataset.item, Number(c.dataset.scale || 3), c);
  });
  if (DATA) {
    run();
    return Promise.resolve();
  }
  return loadSprites().then(run, () => {});
}

/// Draws a one-colour emote icon (9 × 9 rows of "#").
export function drawIcon(ctx, name, color, x = 0, y = 0) {
  const rows = DATA.emoteIcons[name];
  if (rows) paint(ctx, rows, { "#": color }, x, y);
}

/// Legacy helper for the admin: draws an item, scaled by whole pixels.
export async function drawItem(canvas, name, maxScale = 4) {
  await loadSprites();
  itemCanvas(name, maxScale, canvas);
}

// --------------------------------------------------- the visitor's slime

const LOOK_KEY = "slimy.look";
const HATS = ["hat.party", "hat.beanie", "hat.flower", "hat.pumpkin", "hat.crown", "hat.wizard"];
const GLASSES = ["glasses.round", "glasses.shades", "glasses.star"];
const SCARVES = ["scarf.red", "scarf.striped"];

let currentLook = null;

/// The look the visitor picked on the home page, kept in this browser only.
export function savedLook() {
  if (currentLook) return { ...currentLook };
  const look = { stage: "young", skin: "lime", hat: null, glasses: null, scarf: null };
  try {
    const v = JSON.parse(localStorage.getItem(LOOK_KEY) || "null");
    if (v && typeof v === "object") {
      if (Object.hasOwn(SKINS, v.skin)) look.skin = v.skin;
      if (HATS.includes(v.hat)) look.hat = v.hat;
      if (GLASSES.includes(v.glasses)) look.glasses = v.glasses;
      if (SCARVES.includes(v.scarf)) look.scarf = v.scarf;
    }
  } catch {}
  return look;
}

export function saveLook(look) {
  currentLook = { stage: "young", skin: look.skin, hat: look.hat ?? null, glasses: look.glasses ?? null, scarf: look.scarf ?? null };
  try {
    localStorage.setItem(LOOK_KEY, JSON.stringify({ skin: look.skin, hat: look.hat, glasses: look.glasses, scarf: look.scarf }));
  } catch {}
}

// --------------------------------------------------------------- clock

// One timer for every sprite on the page: slimes at 2.5 frames a second like
// the app, island emotes at one icon a second like the island, scenes at 10.
const subs = new Set();
let ticks = 0;
export let clockT = 0;
let timer = null;

const seen = typeof IntersectionObserver === "function"
  ? new IntersectionObserver((entries) => {
    for (const e of entries) if (e.target.__owner) e.target.__owner.visible = e.isIntersecting;
  }, { rootMargin: "120px" })
  : null;

/// Tracks whether `el` is near the viewport, in `owner.visible`.
export function watch(el, owner) {
  owner.visible = true;
  el.__owner = owner;
  seen?.observe(el);
}

/// Calls fn every `every` ticks of 100 ms while the page is visible.
export function onTick(fn, every = 1) {
  const sub = { fn, every };
  subs.add(sub);
  timer ??= setInterval(() => {
    if (document.hidden) return;
    ticks++;
    clockT += 0.1;
    for (const s of subs) if (ticks % s.every === 0) s.fn();
  }, 100);
  return () => subs.delete(sub);
}

// SpriteAnim.posterIndex: the frame that shows an animation best when it can't move.
const POSTER = { idle: 0, play: 1, celebrate: 1, meet: 5 };

/// An animated slime on its own canvas (24 × 20, or 24 × (20 - crop)).
/// Plays one-off animations on top of a looping base, like LiveSlimeView.
export class SlimeActor {
  constructor(canvas, { look = () => savedLook(), base = "idle", crop = 0, mirror = false, still = false } = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.lookFn = typeof look === "function" ? look : () => look;
    this.base = base;
    this.anim = base;
    this.frame = 0;
    this.crop = crop;
    this.mirror = mirror;
    this.still = still;
    this.loops = 1;
    this.done = null;
    this.stillUntil = 0;
    watch(canvas, this);
    // A one-off animation finishes even off screen, so nothing waits on it forever.
    onTick(() => (this.visible || this.done) && this.step(), 4);
    this.draw();
  }
  draw() {
    if (!DATA) return;
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    drawSlime(this.ctx, this.lookFn(), this.anim, this.frame, 0, -this.crop, this.mirror);
  }
  finish() {
    const done = this.done;
    this.anim = this.base;
    this.frame = 0;
    this.done = null;
    this.stillUntil = 0;
    done?.();
    this.draw();
  }
  step() {
    // Reduce Motion: a pose holds still for a moment instead of moving.
    if (this.stillUntil) {
      if (Date.now() >= this.stillUntil) this.finish();
      return;
    }
    if ((calm() || this.still) && this.anim === this.base) return;
    this.frame++;
    if (this.anim !== this.base && this.frame >= frames(this.lookFn().stage || "young", this.anim).length * this.loops) return this.finish();
    this.draw();
  }
  /// Plays `anim` `loops` times, then returns to the base animation.
  play(anim, loops = 2) {
    return new Promise((resolve) => {
      const prev = this.done;
      this.anim = anim;
      this.loops = loops;
      this.frame = calm() ? POSTER[anim] ?? 1 : 0;
      this.stillUntil = calm() ? Date.now() + 900 : 0;
      this.done = resolve;
      prev?.();
      this.draw();
    });
  }
  setBase(anim) {
    this.base = anim;
    if (!this.done) {
      this.anim = anim;
      this.frame = 0;
    }
    this.draw();
  }
}

/// The emote loop on the right of the island: one 9 × 9 icon a second.
export class Reel {
  constructor(canvas, reel = "happyA") {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.reel = reel;
    this.i = 0;
    watch(canvas, this);
    onTick(() => {
      if (!this.visible || calm()) return;
      this.i++;
      this.draw();
    }, 10);
    this.draw();
  }
  set(reel) {
    if (reel === this.reel) return;
    this.reel = reel;
    this.i = 0;
    this.draw();
  }
  draw() {
    if (!DATA) return;
    const list = DATA.emoteReels[this.reel] ?? ["heart"];
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    drawIcon(this.ctx, list[this.i % list.length], REEL_COLORS[this.reel] ?? "#FFFFFF");
  }
}

// ------------------------------------------------- legacy (admin area)

const FPS = 2.5;

/// Sizes a canvas to the largest whole-pixel scale that fits its parent.
function fit(canvas, cols, maxScale) {
  const avail = canvas.parentElement?.clientWidth || cols * maxScale;
  const scale = Math.max(1, Math.min(maxScale, Math.floor(avail / cols)));
  canvas.style.width = cols * scale + "px";
  canvas.style.height = canvas.height * scale + "px";
}

/// A self-contained animated slime, used by the admin area.
export class Slime {
  constructor(canvas, { skin = "lime", stage = "young", anim = "idle", maxScale = 12 } = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.skin = skin;
    this.stage = stage;
    this.base = anim;
    this.anim = anim;
    this.maxScale = maxScale;
    this.frame = 0;
    this.loops = 1;
    this.onDone = null;
    this.ready = loadSprites().then((data) => {
      this.data = data;
      canvas.width = data.width;
      canvas.height = data.height;
      fit(canvas, data.width, maxScale);
      if (canvas.parentElement) new ResizeObserver(() => fit(canvas, data.width, maxScale)).observe(canvas.parentElement);
      this.draw();
      this.timer = setInterval(() => this.tick(), 1000 / FPS);
    });
  }
  frames(anim = this.anim) {
    return frames(this.stage, anim);
  }
  draw() {
    if (!this.data) return;
    const list = this.frames();
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    paint(this.ctx, list[this.frame % list.length], skinColors(this.skin));
  }
  tick() {
    if (calm() && this.anim === this.base) return;
    this.frame++;
    if (this.anim !== this.base && this.frame >= this.frames().length * this.loops) {
      const done = this.onDone;
      this.anim = this.base;
      this.frame = 0;
      this.onDone = null;
      done?.();
    }
    this.draw();
  }
  play(anim, loops = 2) {
    return new Promise((resolve) => {
      this.anim = anim;
      this.loops = loops;
      this.frame = 0;
      this.onDone = resolve;
      this.draw();
    });
  }
  set(props) {
    Object.assign(this, props);
    if (props.base) this.anim = props.base;
    this.frame = 0;
    this.draw();
  }
}
